<?php partial('account_nav',['route'=>$route]); $page=max(1,min(100000,(int)($_GET['page']??1)));$total=(int)$a->db->value('SELECT COUNT(*) FROM cy_notifications WHERE user_id=?',[(int)$me['id']]);$rows=$a->db->all('SELECT * FROM cy_notifications WHERE user_id=? ORDER BY id DESC LIMIT 30 OFFSET ?',[(int)$me['id'],($page-1)*30]); ?><section class="page-hero"><div><span class="eyebrow">NOTHING IMPORTANT GETS LOST</span><h1><?= e($title) ?></h1></div><?= form_start('read_notifications') ?><?php button('Mark all as read','secondary small','check'); ?></form></section><section class="panel glass"><?php foreach ($rows as $row): ?><article class="notification <?= !$row['read_at']?'unread':'' ?>"><span class="notification-icon"><?= icon('bell') ?></span><div class="grow"><h3><?= t($row['title']) ?></h3><p><?= t($row['body']) ?></p><time><?= dt((int)$row['created_at'],'Y.m.d H:i') ?></time><?php if ($row['target_route']): parse_str('r='.$row['target_route'],$target);$r=$target['r']??'notifications';unset($target['r']); ?><a class="text-link" href="<?= e(url($r,$target)) ?>"><?= t('View details') ?><?= icon('arrow') ?></a><?php endif ?></div></article><?php endforeach ?><?php if (!$rows) {empty_state('All quiet. You are up to date.','bell');} partial('pagination',['route'=>$route,'pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/30))]]); ?></section>
